from pathlib import Path

path = Path('ergoapp/src/main/res/layout/activity_main.xml')
text = path.read_text(encoding='utf-8')

# Hide technical angle metrics by default; consumers can reveal them with the Detail button.
old = '''            <TextView\n                android:id="@+id/angleDetailText"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="5dp"\n                android:text="상세: 머리 전방 --% · 상체 변화 --°"\n                android:textColor="#AEB7C4"\n                android:textSize="12sp" />\n'''
new = '''            <TextView\n                android:id="@+id/angleDetailText"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="5dp"\n                android:text="상세: 머리 전방 --% · 상체 변화 --°"\n                android:textColor="#AEB7C4"\n                android:textSize="12sp"\n                android:visibility="gone" />\n'''
if old not in text:
    raise SystemExit('angleDetailText block not found')
text = text.replace(old, new, 1)

old = '''            <LinearLayout\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:orientation="horizontal">\n\n                <Button\n                    android:id="@+id/reportButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="세션 요약"\n                    android:textAllCaps="false" />\n\n                <Button\n                    android:id="@+id/resetButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="초기화"\n                    android:textAllCaps="false" />\n            </LinearLayout>\n'''
new = '''            <LinearLayout\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:orientation="horizontal">\n\n                <Button\n                    android:id="@+id/detailsButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="상세"\n                    android:textAllCaps="false" />\n\n                <Button\n                    android:id="@+id/reportButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="세션 요약"\n                    android:textAllCaps="false" />\n            </LinearLayout>\n\n            <LinearLayout\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:orientation="horizontal">\n\n                <Button\n                    android:id="@+id/helpButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="처음 사용법"\n                    android:textAllCaps="false" />\n\n                <Button\n                    android:id="@+id/resetButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="초기화"\n                    android:textAllCaps="false" />\n            </LinearLayout>\n'''
if old not in text:
    raise SystemExit('report/reset row not found')
text = text.replace(old, new, 1)

anchor = '\n</androidx.constraintlayout.widget.ConstraintLayout>\n'
onboarding = '''\n    <FrameLayout\n        android:id="@+id/onboardingOverlay"\n        android:layout_width="0dp"\n        android:layout_height="0dp"\n        android:background="#E60A0D12"\n        android:clickable="true"\n        android:focusable="true"\n        android:visibility="gone"\n        app:layout_constraintTop_toTopOf="parent"\n        app:layout_constraintBottom_toBottomOf="parent"\n        app:layout_constraintStart_toStartOf="parent"\n        app:layout_constraintEnd_toEndOf="parent">\n\n        <LinearLayout\n            android:layout_width="match_parent"\n            android:layout_height="wrap_content"\n            android:layout_gravity="center"\n            android:layout_margin="24dp"\n            android:background="@drawable/panel_background"\n            android:orientation="vertical"\n            android:padding="22dp">\n\n            <TextView\n                android:layout_width="wrap_content"\n                android:layout_height="wrap_content"\n                android:text="처음 10초 설정"\n                android:textColor="#8FD3FF"\n                android:textSize="13sp"\n                android:textStyle="bold" />\n\n            <TextView\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="7dp"\n                android:text="폰을 몸 옆에 세워주세요"\n                android:textColor="@color/white"\n                android:textSize="25sp"\n                android:textStyle="bold" />\n\n            <TextView\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="12dp"\n                android:lineSpacingExtra="5dp"\n                android:text="1. 머리·어깨·골반이 한 화면에 보이게\\n2. 몸에서 약 60–100cm 옆, 카메라는 상체 높이\\n3. 평소 편한 바른 자세로 앉아주세요"\n                android:textColor="#E6EBF2"\n                android:textSize="15sp" />\n\n            <TextView\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="16dp"\n                android:text="무엇을 할까요?"\n                android:textColor="@color/white"\n                android:textSize="14sp"\n                android:textStyle="bold" />\n\n            <LinearLayout\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="6dp"\n                android:orientation="horizontal">\n\n                <Button\n                    android:id="@+id/onboardingWorkButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="✓ 업무"\n                    android:textAllCaps="false" />\n\n                <Button\n                    android:id="@+id/onboardingStudyButton"\n                    android:layout_width="0dp"\n                    android:layout_height="wrap_content"\n                    android:layout_weight="1"\n                    android:text="공부"\n                    android:textAllCaps="false" />\n            </LinearLayout>\n\n            <TextView\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="12dp"\n                android:text="시작하면 측면 구도를 자동 확인 → 5초 기준 자세 설정 → 세션 시작까지 이어집니다."\n                android:textColor="#C9D1DC"\n                android:textSize="12sp" />\n\n            <Button\n                android:id="@+id/onboardingPrimaryButton"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="14dp"\n                android:text="카메라 맞추기 시작"\n                android:textAllCaps="false"\n                android:textStyle="bold" />\n\n            <Button\n                android:id="@+id/onboardingCloseButton"\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:text="닫기"\n                android:textAllCaps="false" />\n\n            <TextView\n                android:layout_width="match_parent"\n                android:layout_height="wrap_content"\n                android:layout_marginTop="7dp"\n                android:gravity="center"\n                android:text="카메라 영상은 저장하지 않습니다."\n                android:textColor="#98A2B0"\n                android:textSize="10sp" />\n        </LinearLayout>\n    </FrameLayout>\n'''
if anchor not in text:
    raise SystemExit('root layout closing anchor not found')
text = text.replace(anchor, onboarding + anchor, 1)

path.write_text(text, encoding='utf-8')
print('Applied V3.5 consumer layout + onboarding overlay')
